from z3 import *

names = {
    "Eric": Int("Eric"),
    "Arnold": Int("Arnold"),
    "Peter": Int("Peter"),
}

cars = {
    label: Int(label.replace(" ", "_"))
    for label in ["ford f150", "tesla model 3", "toyota camry"]
}

vacations = {
    label: Int(label.replace(" ", "_"))
    for label in ["beach", "mountain", "city"]
}

nationalities = {
    label: Int(label.replace(" ", "_"))
    for label in ["dane", "swede", "brit"]
}

hair_colors = {
    label: Int(label.replace(" ", "_"))
    for label in ["blonde", "black", "brown"]
}

house_styles = {
    label: Int(label.replace(" ", "_"))
    for label in ["colonial", "ranch", "victorian"]
}

solver = Solver()

for group in [names, cars, vacations, nationalities, hair_colors, house_styles]:
    for v in group.values():
        solver.add(v >= 1, v <= 3)
    solver.add(Distinct(*group.values()))

# Clue 1
solver.add(nationalities["swede"] == cars["ford f150"])
# Clue 2
solver.add(hair_colors["blonde"] != 2)
# Clue 3
solver.add(Or(cars["toyota camry"] - names["Arnold"] == 1,
              names["Arnold"] - cars["toyota camry"] == 1))
# Clue 4
solver.add(hair_colors["black"] > house_styles["ranch"])
# Clue 5
solver.add(hair_colors["black"] == nationalities["dane"])
# Clue 6
solver.add(house_styles["victorian"] != 2)
# Clue 7
solver.add(vacations["beach"] == names["Peter"] + 1)
# Clue 8
solver.add(house_styles["colonial"] == hair_colors["blonde"])
# Clue 9
solver.add(hair_colors["black"] == names["Arnold"])
# Clue 10
solver.add(nationalities["dane"] == vacations["beach"])
# Clue 11
solver.add(names["Peter"] == vacations["city"])

if solver.check() == sat:
    model = solver.model()

    def value(expr):
        return model.eval(expr, model_completion=True).as_long()

    def label_for(mapping, house):
        for label, var in mapping.items():
            if value(var) == house:
                return label
        return "?"

    for house in range(1, 4):
        print(
            f"House {house}: "
            f"{label_for(names, house)}, "
            f"{label_for(cars, house)}, "
            f"{label_for(vacations, house)}, "
            f"{label_for(nationalities, house)}, "
            f"{label_for(hair_colors, house)}, "
            f"{label_for(house_styles, house)}"
        )
else:
    print("unsat")

from z3 import *

names = ["Eric", "Arnold", "Alice", "Peter"]
styles = ["craftsman", "ranch", "victorian", "colonial"]
drinks = ["water", "tea", "milk", "coffee"]

name_pos = {n: Int("name_" + n) for n in names}
style_pos = {s: Int("style_" + s) for s in styles}
drink_pos = {d: Int("drink_" + d) for d in drinks}

solver = Solver()

for v in list(name_pos.values()) + list(style_pos.values()) + list(drink_pos.values()):
    solver.add(v >= 1)
    solver.add(v <= 4)

solver.add(Distinct(*list(name_pos.values())))
solver.add(Distinct(*list(style_pos.values())))
solver.add(Distinct(*list(drink_pos.values())))

solver.add(name_pos["Eric"] == drink_pos["water"])
solver.add(drink_pos["milk"] == style_pos["victorian"])
solver.add(style_pos["ranch"] < style_pos["craftsman"])
solver.add(name_pos["Eric"] == 3)
solver.add(name_pos["Arnold"] > name_pos["Alice"])
solver.add(style_pos["ranch"] == name_pos["Arnold"])

def next_to(a, b):
    return Or(a == b + 1, b == a + 1)

solver.add(next_to(name_pos["Eric"], style_pos["victorian"]))
solver.add(drink_pos["tea"] != 1)

if solver.check() == sat:
    model = solver.model()

    name_at = {}
    style_at = {}
    drink_at = {}

    for n in names:
        name_at[model.eval(name_pos[n], True).as_long()] = n
    for s in styles:
        style_at[model.eval(style_pos[s], True).as_long()] = s
    for d in drinks:
        drink_at[model.eval(drink_pos[d], True).as_long()] = d

    for h in range(1, 5):
        print("House {}: {}, {}, {}".format(h, name_at[h], style_at[h], drink_at[h]))
else:
    print("No solution")

