solver.add(drink["watermelon"] == pet["cat"])
solver.add(pet["dog"] > person["Peter"])
solver.add(pet["horse"] + 1 == person["Carol"])
solver.add(person["Eric"] != 5)
solver.add(drink["lime"] == 6)
solver.add(person["Carol"] == 6)
solver.add(Or(pet["bird"] == pet["horse"] - 1, pet["bird"] == pet["horse"] + 1))
