from z3 import *

Peter, Eric, Arnold = Ints('Peter Eric Arnold')
Janelle, Aniya, Holly = Ints('Janelle Aniya Holly')
Romance, ScienceFiction, Mystery = Ints('Romance ScienceFiction Mystery')
Cat, Dog, Fish = Ints('Cat Dog Fish')

s = Solver()

for var in [Peter, Eric, Arnold, Janelle, Aniya, Holly, Romance, ScienceFiction, Mystery, Cat, Dog, Fish]:
    s.add(var >= 1, var <= 3)

s.add(Distinct(Peter, Eric, Arnold))
s.add(Distinct(Janelle, Aniya, Holly))
s.add(Distinct(Romance, ScienceFiction, Mystery))
s.add(Distinct(Cat, Dog, Fish))

s.add(Dog == 1)
s.add(Janelle == Fish)
s.add(Or(Eric - Holly == 2, Holly - Eric == 2))
s.add(Mystery == 1)
s.add(Romance == Peter - 1)

if s.check() == sat:
    m = s.model()

    def pos(v):
        return m.eval(v).as_long()

    name_at = {pos(Peter): "Peter", pos(Eric): "Eric", pos(Arnold): "Arnold"}
    mother_at = {pos(Janelle): "Janelle", pos(Aniya): "Aniya", pos(Holly): "Holly"}
    genre_at = {pos(Romance): "romance", pos(ScienceFiction): "science fiction", pos(Mystery): "mystery"}
    pet_at = {pos(Cat): "cat", pos(Dog): "dog", pos(Fish): "fish"}

    for i in range(1, 4):
        print(f"House {i}: {name_at[i]}, {mother_at[i]}, {genre_at[i]}, {pet_at[i]}")
